<script>
import ApplicationAttachments from "../shared/ApplicationAttachments.vue";

export default {
  name: "ApplicationView",
  components: { ApplicationAttachments },
  props: ["queries"],

  data() {
    return {
      loading: false,
      error: null,
      data: null,
    };
  },

  computed: {
    hiringClosed() {
      return this.data?.advert?.hiringStatus?.code === "closed";
    },

    // The applicant only sees their real application status once hiring
    // has been closed for the advertisement — while hiring is still
    // ongoing, everything reads as "Under Review" regardless of internal
    // status (shortlisted/offered/etc.) to avoid tipping off outcomes early.
    displayStatusCode() {
      return this.hiringClosed
        ? this.data?.statusCode || "underreview"
        : "underreview";
    },
    displayStatusLabel() {
      return this.hiringClosed
        ? this.data?.statusDisplay || "Under Review"
        : "Under Review";
    },
  },

  mounted() {
    if (this.queries?.applicationId) {
      this.load(this.queries.applicationId);
    } else {
      this.error = "No application ID provided.";
    }
  },

  methods: {
    async load(id) {
      this.loading = true;
      this.error = null;
      try {
        const res = await fetch(`/site/position/application/${id}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        this.data = await res.json();
      } catch (err) {
        console.error("application-view load error", err);
        this.error = err.message || "Failed to load application.";
      } finally {
        this.loading = false;
      }
    },

    fmtDate(val) {
      if (!val) return "—";
      try {
        const [y, m, d] = val.split("T")[0].split("-");
        const months = [
          "Jan",
          "Feb",
          "Mar",
          "Apr",
          "May",
          "Jun",
          "Jul",
          "Aug",
          "Sep",
          "Oct",
          "Nov",
          "Dec",
        ];
        if (!m) return y;
        if (!d) return `${months[parseInt(m, 10) - 1]} ${y}`;
        return `${parseInt(d, 10)} ${months[parseInt(m, 10) - 1]} ${y}`;
      } catch {
        return val;
      }
    },

    goBack() {
      this.$router.push({
        path: "/custom/my-applications",
        query: { path: "/lesotho/components/recruitment" },
      });
    },
  },
};
</script>

